proc drt_run {i args} {
    set directory "drt-run-${i}"
    file mkdir "$::env(STEP_DIR)/$directory"
    set output_drc "-output_drc $::env(STEP_DIR)/$directory/$::env(DESIGN_NAME).drc"
    log_cmd detailed_route {*}$args {*}$output_drc
    if { $::env(DRT_SAVE_SNAPSHOTS) } {
        foreach snapshot [glob -nocomplain $::env(STEP_DIR)/drt_iter*.odb] {
            file rename -force $snapshot $::env(STEP_DIR)/$directory/[file tail $snapshot]
        }
    }
    foreach drc_file [glob -nocomplain $::env(STEP_DIR)/$directory/*.drc] {
        file copy -force $drc_file $::env(STEP_DIR)/[file tail $drc_file]
    }
    write_db $::env(STEP_DIR)/$directory/$::env(DESIGN_NAME).odb
}

source $::env(SCRIPTS_DIR)/openroad/common/io.tcl
# SPDX-FileCopyrightText: 2026 Hasan Melih Akbulut
# SPDX-License-Identifier: CERN-OHL-W-2.0
# Reject a lexical value that the native SDC would truncate before loading it.
if {![info exists ::env(TIME_DERATING_CONSTRAINT)]} {
 error "Missing TIME_DERATING_CONSTRAINT"
}
set derate $::env(TIME_DERATING_CONSTRAINT)
if {![string is double -strict $derate] ||
    [catch {expr {double($derate) >= 0 && double($derate) < 100}} valid] || !$valid} {
 error "Invalid TIME_DERATING_CONSTRAINT"
}
set intended_derate [expr {double($derate) / 100.0}]
if {[expr {$derate / 100}] != $intended_derate} {
 error "TIME_DERATING_CONSTRAINT loses precision in the native SDC integer division"
}
puts "DERATE_GUARD percent=$derate early=[expr {1-$intended_derate}] late=[expr {1+$intended_derate}]"

read_current_odb

set_propagated_clock [all_clocks]
foreach {name period} {clk_i 20 pcie_clk_i 4 eth_rx_clk_i 8 eth_tx_clk_i 8} {
    set clock [get_clocks $name]
    if {[llength $clock] != 1 || abs([get_property $clock period]-$period)>1e-9} {
        error "Original physical clock budget changed: $name"
    }
}
foreach clock [all_clocks] {
    if {![get_property $clock is_propagated]} {error "PostCTS ideal clock"}
}
puts "%OL_CREATE_REPORT high-fanout.rpt"
foreach net [[ord::get_db_block] getNets] {
    if {[$net getSigType] in {POWER GROUND}} {continue}
    set pins [$net getITerms]
    if {[llength $pins] < 128} {continue}
    set drivers {}
    foreach pin $pins {
        if {[$pin getIoType] == "OUTPUT"} {
            lappend drivers "[[$pin getInst] getName]/[[$pin getMTerm] getName]"
        }
    }
    puts [list [$net getName] [$net getSigType] [llength $pins] $drivers]
}
puts "%OL_END_REPORT"
source "/home/runner/work/nssoc/nssoc/hw/soc/flow/prune_orphan_guides.tcl"
puts "REMOVED_ORPHAN_GUIDES [prune_orphan_guides [ord::get_db_block]]"

# Create NDRs
if { [info exists ::env(NON_DEFAULT_RULES)] } {
    dict for {ndr_name values} $::env(NON_DEFAULT_RULES) {
        puts "Creating NDR for $ndr_name:"
        dict with values {
            puts "  width: $width"
            puts "  spacing: $spacing"
            puts "  via: $via"

            if {$via eq "None"} {
                create_ndr -name $ndr_name \
                    -width $width \
                    -spacing $spacing
            } else {
                create_ndr -name $ndr_name \
                    -width $width \
                    -spacing $spacing \
                    -via $via
            }
        }
    }
}

# Assign NDRs to nets
if { [info exists ::env(DRT_ASSIGN_NDR)] } {
    dict for {net_regex ndr_name} $::env(DRT_ASSIGN_NDR) {
        puts "\[INFO\] Assigning NDR '$ndr_name' to nets matching '$net_regex'"
        if { $net_regex != {^$} } {
            set odb_nets [$::block getNets]
            foreach net $odb_nets {
                set net_name [odb::dbNet_getName $net]
                if { [regexp "$net_regex" $net_name full] } {
                    puts "\[INFO\] Net '$net_name' matched '$net_regex', assigning NDR '$ndr_name'…"
                    assign_ndr -ndr $ndr_name -net $net_name
                }
            }
        }
    }
}

set_thread_count $::env(DRT_THREADS)

set drc_report_iter_step_arg ""
if { $::env(DRT_SAVE_SNAPSHOTS) } {
    set_debug_level DRT snapshot 1
    set drc_report_iter_step_arg "-drc_report_iter_step 1"
    detailed_route_debug -snapshot_dir "$::env(STEP_DIR)"
}
if { [info exists ::env(DRT_SAVE_DRC_REPORT_ITERS)] } {
    set drc_report_iter_step_arg "-drc_report_iter_step $::env(DRT_SAVE_DRC_REPORT_ITERS)"
}

# The input has only stale data wires removed. Source geometry, netlist,
# power and clock wires were independently checked before this native step.
set_routing_layers -signal Metal2-TopMetal2 -clock Metal4-TopMetal2
set_global_routing_layer_adjustment * 0.0
# General adjustment does not overwrite persisted per-layer adjustments.
set nssoc_adjustment_report [open "$::env(STEP_DIR)/native-layer-adjustments.tsv" w]
puts $nssoc_adjustment_report "layer\tbefore\tafter"
foreach nssoc_layer_name {Metal2 Metal3 Metal4 Metal5 TopMetal1 TopMetal2} {
    set nssoc_layer [[ord::get_db_tech] findLayer $nssoc_layer_name]
    set nssoc_before [$nssoc_layer getLayerAdjustment]
    set_global_routing_layer_adjustment $nssoc_layer_name 0.0
    set nssoc_after [$nssoc_layer getLayerAdjustment]
    puts $nssoc_adjustment_report "$nssoc_layer_name\t$nssoc_before\t$nssoc_after"
    puts "NSSOC_LAYER_ADJUSTMENT $nssoc_layer_name $nssoc_before -> $nssoc_after"
    if {abs($nssoc_after) > 1e-9} { error "Persisted layer adjustment was not cleared" }
}
close $nssoc_adjustment_report
set_macro_extension 0
global_route -congestion_iterations 200 -verbose
write_guides "$::env(STEP_DIR)/fresh-fanout.guide"
write_db "$::env(STEP_DIR)/fresh-fanout-global.odb"
puts "NSSOC_FRESH_FANOUT_GUIDES_FROM_CURRENT_NATIVE_PINS"
set i 0

set drt_args [list]
lappend drt_args -droute_end_iter $::env(DRT_OPT_ITERS)
lappend drt_args -or_seed 42
lappend drt_args -verbose 1
lappend drt_args {*}$drc_report_iter_step_arg
drt_run $i {*}$drt_args

incr i

if { ![info exists ::env(DIODE_CELL)] } {
    puts "\[INFO\] Skipping post-DRT antenna repair: 'DIODE_CELL' not set."
} elseif { $::env(DRT_ANTENNA_REPAIR_ITERS) == 0 } {
    puts "\[INFO\] Skipping post-DRT antenna repair: DRT_ANTENNA_REPAIR_ITERS set to 0."
} else {
    set diode_cell [lindex [split $::env(DIODE_CELL) "/"] 0]

    set arg_list [list]
    lappend arg_list $diode_cell
    lappend arg_list -ratio_margin $::env(GRT_ANTENNA_REPAIR_MARGIN)
    append_if_flag arg_list GRT_ALLOW_CONGESTION -allow_congestion
    append_if_flag arg_list DRT_ANTENNA_REPAIR_JUMPER_ONLY -jumper_only
    append_if_flag arg_list DRT_ANTENNA_REPAIR_DIODE_ONLY -diode_only

    while {$i <= $::env(DRT_ANTENNA_REPAIR_ITERS) && [log_cmd check_antennas]} {
        puts "\[INFO\] Running antenna repair iteration $i…"
        # Native ANT WireBuilder recognizes net-level ROUTED metadata when
        # deciding whether an existing detailed wire must be synthesized.
        # Change only that metadata during ANT; keep its FIXED encoded wire.
        set nssoc_fixed_net [[ord::get_db_block] findNet clknet_3_5_0_pcie_clk_i]
        if {[$nssoc_fixed_net getWireType] ne "FIXED"} {
            error "Fixed clock metadata missing before native antenna repair"
        }
        set nssoc_fixed_wire [$nssoc_fixed_net getWire]
        if {$nssoc_fixed_wire eq "NULL"} {error "Fixed clock wire missing"}
        $nssoc_fixed_net setWireType ROUTED
        set nssoc_ant_code [catch {
            set diodes_inserted [log_cmd repair_antennas {*}$arg_list]
        } nssoc_ant_result nssoc_ant_options]
        $nssoc_fixed_net setWireType FIXED
        if {[$nssoc_fixed_net getWire] ne $nssoc_fixed_wire} {
            error "Native antenna repair replaced the physical fixed clock wire"
        }
        if {$nssoc_ant_code} {
            return -options $nssoc_ant_options $nssoc_ant_result
        }
        puts "NSSOC_FIXED_CLOCK_ANTENNA_METADATA_RESTORED"

        if {$diodes_inserted || $::env(DRT_ANTENNA_REPAIR_JUMPER_ONLY)} {
            drt_run $i {*}$drt_args
        } else {
            puts "\[INFO\] No diodes inserted. Ending antenna repair iterations."
            break
        }
        incr i
    }
}
write_views
